from collections import deque

def has_cycle_of_length(adj, target_len):
    n = len(adj)
    for start in range(n):
        # BFS: (current, parent, depth)
        # Actually, we need simple BFS with parent tracking
        visited = {}
        q = deque()
        q.append((start, -1, 0))
        visited[(start, -1)] = 0
        while q:
            v, parent, depth = q.popleft()
            if depth == target_len:
                continue
            for u in adj[v]:
                if u == parent:
                    continue
                if u == start and depth + 1 == target_len:
                    return True  # found cycle
                if (u, v) not in visited:
                    visited[(u, v)] = depth + 1
                    q.append((u, v, depth + 1))
    return False

