from collections import deque

def shortest_cycle_length(adj):
    n = len(adj)
    min_len = n+1
    for start in range(n):
        # BFS from start
        dist = [-1]*n
        parent = [-1]*n
        q = deque([start])
        dist[start] = 0
        while q:
            v = q.popleft()
            for u in adj[v]:
                if dist[u] == -1:
                    dist[u] = dist[v] + 1
                    parent[u] = v
                    q.append(u)
                elif parent[v] != u and parent[u] != v:
                    # Found cycle: v-u edge plus paths to start
                    cycle_len = dist[v] + dist[u] + 1
                    if cycle_len < min_len:
                        min_len = cycle_len
                        # early exit if found 3-cycle
                        if min_len == 3:
                            return 3
        # reset for next start
    return min_len

